import json
from decimal import Decimal

r1 = json.loads(fji1)
r2 = json.loads(fji2)
got = json.loads(out)
assert got["alpha"] == r1["alpha"] == r2["alpha"]
W = Decimal("1.5") + Decimal("2.5")
for i, iv in enumerate(got["intervals"]):
    s1, s2 = r1["intervals"][i], r2["intervals"][i]
    assert iv["start"] == s1["start"] == s2["start"]
    assert iv["end"] == s1["end"] == s2["end"]
    # pick: weight 1.5 for fji1's pick, 2.5 for fji2's
    p1, p2 = tuple(s1["pick"]), tuple(s2["pick"])
    w = {p1: Decimal("1.5")}
    w[p2] = w.get(p2, Decimal(0)) + Decimal("2.5")
    best = max(w, key=lambda p: (w[p], tuple(chr(0x10FFFF) - 0 for _ in ())))
    best = min((p for p in w if w[p] == max(w.values())))
    assert tuple(iv["pick"]) == best, (iv, best)
    assert abs(iv["consistency"] - float(max(w.values()) / W)) < 1e-6
    # region/window: single region/window per report
    assert iv["region"] in ("r1", "r2")
    assert iv["window"] in ("w1", "w2")
    # factors
    for cat, members in (("weather", ["caseA"]), ("cover", []),
                         ("morphology", ["caseB"])):
        if not members:
            assert iv["factors"][cat] == 0.0
            continue
        gains1 = {c["key"]: c["gain"] for c in s1["cases"]}
        gains2 = {c["key"]: c["gain"] for c in s2["cases"]}
        total = sum(
            Decimal("1.5") * Decimal(str(gains1[m]))
            + Decimal("2.5") * Decimal(str(gains2[m]))
            for m in members
        )
        expect = float(total / (W * len(members)))
        assert abs(iv["factors"][cat] - expect) < 1e-6, (cat, iv, expect)
print("end-to-end OK")

