import json
from decimal import Decimal

from urban_micro import (
    decision_priority_consensus,
    decision_priority_matrix,
    frontier_interval_attribution,
    frontier_joint_intervals,
    portfolio_attribution,
    scenario_sensitivity,
)

edges = [("a", "b")]
lags = [1]
labels = {"a": "L", "b": "L"}
windows = {0: "w", 3600: "w"}
weights_g = {("L", "w", 1): 1.0}
kinds = {"s1": ("green", 0.5), "s2": ("roof", 0.8)}


def row(t, c, delta):
    return (t, c, 1.0, 1.0 + delta, delta, 0.0, 0.0, 0.0)


def make_sens(delta1, delta2):
    base = [row(0, "a", 0.1), row(0, "b", 0.2),
            row(3600, "a", 0.15), row(3600, "b", 0.25)]
    sets = {
        "s1": [row(0, "a", delta1), row(0, "b", 0.2),
               row(3600, "a", delta1), row(3600, "b", 0.25)],
        "s2": [row(0, "a", delta2), row(0, "b", 0.2),
               row(3600, "a", delta2), row(3600, "b", 0.25)],
    }
    return scenario_sensitivity(
        base, sets, edges, lags, labels, windows, weights_g, kinds
    )


def make_matrix(d1, d2):
    reports = {
        ("r1", "w1"): make_sens(d1, d2),
        ("r2", "w2"): make_sens(d1 + 0.1, d2),
    }
    return decision_priority_matrix(
        reports, {("r1", "w1"): 1.0, ("r2", "w2"): 2.0}
    )


evidence = {}
for by, group in (("region", "r1"), ("region", "r2"),
                  ("window", "w1"), ("window", "w2")):
    for cand in ("s1", "s2"):
        evidence[("snap1", by, group, cand)] = True

consensus = []
for i in range(7):
    base_m = make_matrix(1.0 + 0.05 * i, 2.0 - 0.03 * i)
    snap_m = make_matrix(1.1 + 0.05 * i, 1.95 - 0.03 * i)
    consensus.append(
        decision_priority_consensus(base_m, {"snap1": snap_m}, evidence)
    )
scen_names = [f"sc{i}" for i in range(7)]

# 12 panels: regions of 6, windows of 6, so every group's sign-permutation
# p can reach 2/64 and both candidates come out significant everywhere
panels = []
for i in range(12):
    region = "r1" if i < 6 else "r2"
    window = "w1" if i % 2 == 0 else "w2"
    panels.append((region, window))

pa_reports = {}
for i, panel in enumerate(panels):
    pw = {name: 1.0 for name in scen_names}
    gains = {
        name: {"s1": 1.0 + 0.1 * i + 0.02 * j, "s2": 2.0 - 0.05 * i}
        for j, name in enumerate(scen_names)
    }
    pa_reports[panel] = portfolio_attribution(
        dict(zip(scen_names, consensus)), pw, gains, ["s1", "s2"]
    )

panel_weights = {panel: 1.0 for panel in panels}
cases = {
    "caseA": {
        "cost": {"s1": 1.0, "s2": 1.0},
        "gain": {"s1": 1.0, "s2": 1.5},
    },
    "caseB": {
        "cost": {"s1": 2.0, "s2": 1.0},
        "gain": {"s1": 1.0, "s2": 1.0},
    },
}
cost = {"s1": 1.0, "s2": 1.0}
limits = [0.5, 1.0, 1.5, 2.0, 2.5]

fji1 = frontier_joint_intervals(
    pa_reports, panel_weights, cost, limits, cases
)
print("fji1:", fji1)
iv1 = json.loads(fji1)["intervals"]
assert any(iv["pick"] for iv in iv1), "still degenerate"
print(f"segments: {len(iv1)}, picks: {[iv['pick'] for iv in iv1]}")

# second report: same structure, different case gain multipliers
cases2 = {
    "caseA": {
        "cost": {"s1": 1.0, "s2": 1.0},
        "gain": {"s1": 1.2, "s2": 1.3},
    },
    "caseB": {
        "cost": {"s1": 1.5, "s2": 1.0},
        "gain": {"s1": 1.1, "s2": 1.0},
    },
}
fji2 = frontier_joint_intervals(
    pa_reports, panel_weights, cost, limits, cases2
)
iv2 = json.loads(fji2)["intervals"]
assert len(iv2) == len(iv1)
assert [(iv["start"], iv["end"]) for iv in iv2] == [
    (iv["start"], iv["end"]) for iv in iv1
]

out = frontier_interval_attribution(
    {("north", "day"): fji1, ("south", "night"): fji2},
    {("north", "day"): 1.5, ("south", "night"): 2.5},
    {"caseA": "weather", "caseB": "morphology"},
)
print("attribution:", out)

# independent recomputation
r1, r2 = json.loads(fji1), json.loads(fji2)
got = json.loads(out)
W1, W2 = Decimal("1.5"), Decimal("2.5")
W = W1 + W2
assert got["alpha"] == r1["alpha"]
for i, iv in enumerate(got["intervals"]):
    s1, s2 = r1["intervals"][i], r2["intervals"][i]
    assert iv["start"] == s1["start"] and iv["end"] == s1["end"]
    p1, p2 = tuple(s1["pick"]), tuple(s2["pick"])
    w = {p1: W1}
    w[p2] = w.get(p2, Decimal(0)) + W2
    top = max(w.values())
    best = min(p for p in w if w[p] == top)
    assert tuple(iv["pick"]) == best, (iv, best)
    assert abs(iv["consistency"] - float(top / W)) < 1e-6
    m1 = sum(c["gain"] for c in s1["cases"]) / len(s1["cases"])
    m2 = sum(c["gain"] for c in s2["cases"]) / len(s2["cases"])
    exp_region = min(
        ("north", "south"),
        key=lambda r: ((W1 if r == "north" else W2)
                       * Decimal(str(m1 if r == "north" else m2))
                       / (W1 if r == "north" else W2), r),
    )
    assert iv["region"] == exp_region
    exp_window = min(
        ("day", "night"),
        key=lambda r: (Decimal(str(m1 if r == "day" else m2)), r),
    )
    assert iv["window"] == exp_window
    gains1 = {c["key"]: c["gain"] for c in s1["cases"]}
    gains2 = {c["key"]: c["gain"] for c in s2["cases"]}
    for cat, members in (("weather", ["caseA"]), ("cover", []),
                         ("morphology", ["caseB"])):
        if not members:
            assert iv["factors"][cat] == 0.0
            continue
        total = sum(
            W1 * Decimal(str(gains1[m])) + W2 * Decimal(str(gains2[m]))
            for m in members
        )
        assert abs(iv["factors"][cat] - float(total / (W * len(members)))) < 1e-6
print("end-to-end OK (non-degenerate, multi-segment)")

